mapper.select:
select coalesce(sum(amount),0) from biz_operating_fact where project_id=#{projectId} and biz_date between #{from} and #{to}
  and fact_kind='COST' and status in('CONFIRMED','REVERSED')
  and coalesce(category_code,'') not in('COMPANY_PUBLIC_COST','PERSONNEL_COST','PROJECT_BONUS_COST','INTERNAL_PROJECT_COST')
